  8	public final class CircularQueue<T> extends AbstractQueue<T> {
  9	
 10	    private static final String EMPTY_QUEUE_MESSAGE = "Queue is empty.";
 11	    private static final String FULL_QUEUE_MESSAGE = "Queue is full.";
 12	
 13	    private final Object[] elements;
 14	    private int head;
 15	    private int tail;
 16	    private int size;
 17	    private int modificationCount;
 18	
 19	    public CircularQueue(int capacity) {
 20	        if (capacity <= 0) {
 21	            throw new IllegalArgumentException("Capacity must be positive.");
 22	        }
 23	
 24	        this.elements = new Object[capacity];
 25	        this.head = 0;
 26	        this.tail = 0;
 27	        this.size = 0;
 28	        this.modificationCount = 0;
 29	    }
 30	
 31	    public void enqueue(T value) {
 32	        if (!offer(value)) {
 33	            throw new IllegalStateException(FULL_QUEUE_MESSAGE);
 34	        }
 35	    }
 36	
 37	    public T dequeue() {
 38	        requireNotEmpty();
 39	        T value = removeHead();
 40	        modificationCount++;
 41	        return value;
 42	    }
 43	
 44	    public T peekFront() {
 45	        requireNotEmpty();
 46	        return elementAt(head);
 47	    }
 48	
 49	    public T peekRear() {
 50	        requireNotEmpty();
 51	        return elementAt(indexFromHead(size - 1));
 52	    }
 53	
 54	    public T getFront() {
 55	        return peekFront();
 56	    }
 57	
 58	    public T getRear() {
 59	        return peekRear();
 60	    }
 61	
 62	    @Override
 63	    public boolean isEmpty() {
 64	        return size == 0;
 65	    }
 66	
 67	    public boolean isFull() {
 68	        return size == elements.length;
 69	    }
 70	
 71	    @Override
 72	    public boolean offer(T value) {
 73	        Objects.requireNonNull(value, "Queue elements must be non-null.");
 74	        if (isFull()) {
 75	            return false;
 76	        }
 77	
 78	        insertAtTail(value);
 79	        modificationCount++;
 80	        return true;
 81	    }
 82	
 83	    @Override
 84	    public T poll() {
 85	        if (isEmpty()) {
 86	            return null;
 87	        }
 88	
 89	        T value = removeHead();
 90	        modificationCount++;
 91	        return value;
 92	    }
 93	
 94	    @Override
 95	    public T peek() {
 96	        if (isEmpty()) {
 97	            return null;
 98	        }
 99	        return elementAt(head);
100	    }
101	
102	    @Override
103	    public int size() {
104	        return size;
105	    }
106	
107	    public int capacity() {
108	        return elements.length;
109	    }
110	
111	    public int remainingCapacity() {
112	        return capacity() - size;
113	    }
114	
115	    @Override
116	    public void clear() {
117	        Arrays.fill(elements, null);
118	        head = 0;
119	        tail = 0;
120	        size = 0;
121	        modificationCount++;
122	    }
123	
124	    @Override
125	    public Iterator<T> iterator() {
126	        return new QueueIterator();
127	    }
128	
129	    @Override
130	    public String toString() {
131	        StringBuilder builder = new StringBuilder("[");
132	        for (int i = 0; i < size; i++) {
133	            if (i > 0) {
134	                builder.append(", ");
135	            }
136	            builder.append(elementAt(indexFromHead(i)));
137	        }
138	        return builder.append(']').toString();
139	    }
140	
141	    private int advance(int index) {
142	        return (index + 1) % elements.length;
143	    }
144	
145	    private int indexFromHead(int offset) {
146	        return (head + offset) % elements.length;
147	    }
148	
149	    private void requireNotEmpty() {
150	        if (isEmpty()) {
151	            throw new IllegalStateException(EMPTY_QUEUE_MESSAGE);
152	        }
153	    }
154	
155	    private void insertAtTail(T value) {
156	        elements[tail] = value;
157	        tail = advance(tail);
158	        size++;
159	    }
160	
161	    @SuppressWarnings("unchecked")
162	    private T removeHead() {
163	        T value = elementAt(head);
164	        elements[head] = null;
165	        head = advance(head);
166	        size--;
167	        return value;
168	    }
169	
170	    @SuppressWarnings("unchecked")
171	    private T elementAt(int index) {
172	        return (T) elements[index];
173	    }
174	
175	    private final class QueueIterator implements Iterator<T> {
176	
177	        private final int expectedModificationCount = modificationCount;
178	        private int offset;
179	
180	        @Override
181	        public boolean hasNext() {
182	            ensureUnmodified();
183	            return offset < size;
184	        }
185	
186	        @Override
187	        public T next() {
188	            ensureUnmodified();
189	            if (!hasNext()) {
190	                throw new NoSuchElementException();
191	            }
192	
193	            T value = elementAt(indexFromHead(offset));
194	            offset++;
195	            return value;
196	        }
197	
198	        private void ensureUnmodified() {
199	            if (expectedModificationCount != modificationCount) {
200	                throw new ConcurrentModificationException();
201	            }
202	        }
203	    }
204	}
